        {
            ["arc.dieuhau.c10m10"] = ("The last shot at Roc: \"That one was for you, old friend.\"", "Phát bắn cuối vào Roc: \"Phát đó là cho cậu, bạn cũ.\""),
            ["arc.dieuhau.c10m12"] = ("The duel with Raven over Skyhold.", "Trận đấu tay đôi với Raven trên bầu trời Skyhold."),
            ["arc.dieuhau.c3m05"] = ("Knows Raven's mark: Raven shot down his wingman.", "Nhận ra dấu hiệu của Raven: kẻ đã bắn hạ bạn bay của anh."),
            ["arc.dieuhau.i3m01"] = ("Shot down behind the lines.", "Bị bắn rơi sau phòng tuyến địch."),
            ["arc.dieuhau.i3m04"] = ("Brought home over Frostpeak.", "Được đưa về nhà qua Frostpeak."),
            ["arc.dieuhau.title"] = ("Hawk's story", "Câu chuyện của Hawk"),
            ["arc.khai.c12m10"] = ("Brings Icarus down, then turns down a seat in the government.", "Hạ Icarus, rồi từ chối một ghế trong chính phủ."),
            ["arc.khai.c1m01"] = ("Leads the landing at Stormbeach.", "Chỉ huy cuộc đổ bộ ở Stormbeach."),
            ["arc.khai.c6m14"] = ("Talks with Varga during the ceasefire.", "Nói chuyện với Varga trong giờ ngừng bắn."),
            ["arc.khai.c7m10"] = ("Frees Veyra and loses a third of the army to Thorne.", "Giải phóng Veyra và mất một phần ba quân đội vào tay Thorne."),
            ["arc.khai.title"] = ("Kade's story", "Câu chuyện của Kade"),
            ["arc.linh.c1m10"] = ("Counts Brandt's files and finds Varga.", "Đếm hồ sơ của Brandt và tìm ra Varga."),
            ["arc.linh.c4m13"] = ("Notices that Thorne's column never came.", "Để ý rằng đoàn xe của Thorne không bao giờ tới."),
            ["arc.linh.c5m09"] = ("Hears \"Titan\" in Venn's traffic.", "Nghe thấy \"Titan\" trong liên lạc của Venn."),
            ["arc.linh.c6m15"] = ("Finds Thorne's HQ on a Hegemon band.", "Phát hiện sở chỉ huy của Thorne trên băng tần Hegemon."),
            ["arc.linh.c7m10"] = ("Sees Thorne's base turn before anyone else.", "Thấy căn cứ của Thorne trở giáo trước tất cả mọi người."),
            ["arc.linh.title"] = ("Nadia's story", "Câu chuyện của Nadia"),
            ["arc.mai.c11m11"] = ("Takes the guidance computer that tracks Icarus.", "Lấy được máy tính dẫn đường theo dõi Icarus."),
            ["arc.mai.c12m10"] = ("Her Behemoth fights beside the brigade at Helion.", "Chiếc Behemoth của bà chiến đấu cùng lữ đoàn ở Helion."),
            ["arc.mai.c1m04"] = ("Builds the brigade's first field base in a day.", "Dựng căn cứ dã chiến đầu tiên của lữ đoàn trong một ngày."),
            ["arc.mai.c2m05"] = ("Knows Inferno's cooling line: she drew it.", "Nhận ra đường ống làm mát của Inferno: chính bà đã vẽ nó."),
            ["arc.mai.c2m11"] = ("Tells Kade she designed Hegemon's first Behemoth.", "Kể với Kade rằng bà đã thiết kế chiếc Behemoth đầu tiên của Hegemon."),
            ["arc.mai.c6m03"] = ("Restarts a captured Behemoth: Matilda.", "Khởi động lại một chiếc Behemoth bắt được: Matilda."),
            ["arc.mai.i1m03"] = ("Finds her initials on Behemoth Mk.0.", "Tìm thấy chữ ký tắt của mình trên Behemoth Mk.0."),
            ["arc.mai.title"] = ("Mara's story", "Câu chuyện của Mara"),
            ["arc.varga.c12m10"] = ("Falls like a soldier at Helion.", "Ngã xuống như một người lính ở Helion."),
            ["arc.varga.c2m01"] = ("Greets the brigade like a soldier.", "Chào lữ đoàn như một người lính."),
            ["arc.varga.c2m11"] = ("Sends the Behemoth at Red Rock.", "Tung Behemoth vào trận ở Red Rock."),
            ["arc.varga.c6m14"] = ("The ceasefire: his only talk with Kade.", "Cuộc ngừng bắn: lần duy nhất ông nói chuyện với Kade."),
            ["arc.varga.title"] = ("Varga's story", "Câu chuyện của Varga"),
            ["campaign.choiceKicker"] = ("{chapter} · a choice", "{chapter} · lựa chọn"),
            ["campaign.choiceTag"] = ("A choice", "Lựa chọn"),
            ["campaign.choose"] = ("Choose", "Chọn"),
            ["campaign.notTaken"] = ("Not taken", "Không chọn"),
            ["campaign.notTakenNote"] = ("You chose the other way here.", "Bạn đã chọn hướng còn lại ở đây."),
            ["campaign.storyLoot"] = ("Story reward", "Phần thưởng cốt truyện"),
            ["comic.1.1"] = ("Stormbeach. Three years of occupation, and we came in with the tide.", "Stormbeach. Ba năm bị chiếm đóng, và ta đổ bộ theo con nước."),
            ["comic.1.2"] = ("A field base in a day. Don't ask me how. Ask me for more steel.", "Một căn cứ dã chiến trong một ngày. Đừng hỏi tôi làm thế nào. Cứ xin thêm thép cho tôi."),
            ["comic.1.3"] = ("The Bastion held for a week. You broke it in a morning, Colonel.", "Bastion trụ được một tuần. Ông phá nó trong một buổi sáng, đại tá."),
            ["comic.1.4"] = ("Brandt's files. One name on every page: Varga.", "Hồ sơ của Brandt. Một cái tên trên mọi trang: Varga."),
            ["comic.10.1"] = ("Just you and me, Hawk. No ground fire, no excuses.", "Chỉ còn ta với ngươi, Hawk. Không hỏa lực mặt đất, không viện cớ."),
            ["comic.10.2"] = ("That one was for you, old friend.", "Phát đó là cho cậu, bạn cũ."),
            ["comic.10.3"] = ("Skyhold is ours. The sky is next.", "Skyhold là của ta. Tiếp theo là bầu trời."),
            ["comic.11.1"] = ("For the record: our first satellite reached orbit this morning.", "Xin thông báo: vệ tinh đầu tiên của chúng tôi đã lên quỹ đạo sáng nay."),
            ["comic.11.2"] = ("Their guidance computer. With this I can tell where Icarus will be.", "Máy tính dẫn đường của chúng. Có nó, tôi biết Icarus sẽ ở đâu."),
            ["comic.11.3"] = ("The Array has fallen. Helion is all that's left.", "Skygate đã thất thủ. Chỉ còn lại Helion."),
            ["comic.12.1"] = ("Like soldiers, Colonel. To the end.", "Như những người lính, đại tá. Tới cùng."),
            ["comic.12.2"] = ("Matilda, forward. One last time.", "Matilda, tiến lên. Lần cuối cùng."),
            ["comic.12.3"] = ("They still don't understand.", "Họ vẫn chưa hiểu."),
            ["comic.12.4"] = ("It's over. Three years. Take us home.", "Kết thúc rồi. Ba năm. Đưa chúng ta về nhà."),
            ["comic.13.1"] = ("Every bolt Hegemon ever bought is written down in here.", "Mọi con bu lông Hegemon từng mua đều được ghi trong này."),
            ["comic.13.2"] = ("M. L. My initials. On the first one they ever built.", "M. L. Chữ ký tắt của tôi. Trên chiếc đầu tiên họ từng chế tạo."),
            ["comic.13.3"] = ("We take the drawings. They build no more of these here.", "Ta mang bản vẽ đi. Ở đây chúng sẽ không chế tạo thêm chiếc nào nữa."),
            ["comic.14.1"] = ("Keep your head down, Doctor. Mirewood bites.", "Cúi đầu xuống, tiến sĩ. Mirewood cắn người đấy."),
            ["comic.14.2"] = ("The border is right there. I could just drive across.", "Biên giới ở ngay đó. Tôi có thể lái xe qua là xong."),
            ["comic.14.3"] = ("No. I stay. I built these machines. I'll help take them apart.", "Không. Tôi ở lại. Tôi đã tạo ra những cỗ máy này. Tôi sẽ giúp tháo dỡ chúng."),
            ["comic.15.1"] = ("Down behind the lines. Raven is circling. Waiting.", "Rơi sau phòng tuyến địch. Raven đang lượn vòng. Chờ đợi."),
            ["comic.15.2"] = ("Crown's column. We came for our pilot.", "Đoàn xe Crown. Chúng tôi tới đón phi công của mình."),
            ["comic.15.3"] = ("Home. Give me a jet. This isn't over.", "Về nhà rồi. Cho tôi một chiếc máy bay. Chuyện này chưa xong đâu."),
            ["comic.2.1"] = ("A soldier's greeting, Colonel. Then a soldier's war.", "Một lời chào của người lính, đại tá. Rồi một cuộc chiến của người lính."),
            ["comic.2.2"] = ("I drew that machine. I know where it bleeds.", "Tôi đã vẽ cỗ máy đó. Tôi biết nó chảy máu ở đâu."),
            ["comic.2.3"] = ("Thorne's army on your left. Together nobody stops us, Kade.", "Quân của Thorne bên cánh trái anh. Cùng nhau thì không ai cản nổi ta, Kade."),
            ["comic.3.1"] = ("That mark on the Harpy's tail. Raven. He shot down my wingman.", "Dấu hiệu trên đuôi Harpy. Raven. Hắn đã bắn hạ bạn bay của tôi."),
            ["comic.3.2"] = ("Winter always comes back, Colonel.", "Mùa đông luôn quay lại, đại tá."),
            ["comic.3.3"] = ("The pass is open. Next stop, the sea.", "Con đèo đã mở. Điểm dừng tiếp theo: biển."),
            ["comic.4.1"] = ("The port is ours. Tempest's gun came out of the water in one piece.", "Cảng là của ta. Khẩu pháo của Tempest được vớt lên còn nguyên."),
            ["comic.4.2"] = ("A fleet is a line in a ledger, Colonel. You have closed mine.", "Hạm đội chỉ là một dòng trong sổ sách, đại tá. Ngươi vừa khóa sổ của ta."),
            ["comic.4.3"] = ("Thorne's column never came. Again. I'm starting a file.", "Đoàn xe của Thorne lại không tới. Lại nữa. Tôi bắt đầu lập hồ sơ."),
            ["comic.5.1"] = ("I built the swarm to find people under rubble.", "Tôi tạo ra bầy drone để tìm người dưới đống đổ nát."),
            ["comic.5.2"] = ("Matriarch is down. The woman who built her is walking towards us.", "Matriarch đã rơi. Người tạo ra nó đang bước về phía ta."),
            ["comic.5.3"] = ("Here is the Icarus drive. Stop him before he finishes it.", "Đây là bộ đẩy của Icarus. Hãy chặn ông ta trước khi ông ta hoàn thành nó."),
            ["comic.6.1"] = ("One hour of ceasefire, Colonel. For the wounded. Then we are enemies again.", "Một giờ ngừng bắn, đại tá. Cho những người bị thương. Rồi ta lại là kẻ thù."),
            ["comic.6.2"] = ("Moloch's factory floor, still warm. My walls held, Colonel.", "Sàn xưởng của Moloch vẫn còn ấm. Tường của tôi đã trụ vững, đại tá."),
            ["comic.6.3"] = ("Thorne was late again. I can't call it luck any more.", "Thorne lại tới muộn. Tôi không thể gọi đó là may rủi được nữa."),
            ["comic.7.1"] = ("Veyra. The capital. The whole Accord is watching.", "Veyra. Thủ đô. Cả Accord đang dõi theo."),
            ["comic.7.2"] = ("Thorne's base just turned its guns on us. I saw it first.", "Căn cứ của Thorne vừa quay pháo vào ta. Tôi thấy trước tiên."),
            ["comic.7.3"] = ("Have you seen what they are about to launch, Kade? I have.", "Anh đã thấy thứ họ sắp phóng lên chưa, Kade? Tôi thì thấy rồi."),
            ["comic.7.4"] = ("Veyra is free. A third of the army walked out with him.", "Veyra đã tự do. Một phần ba quân đội đã theo hắn bỏ đi."),
            ["comic.8.1"] = ("The miners know every tunnel. Thorne only knows the maps.", "Thợ mỏ thuộc từng đường hầm. Thorne chỉ biết bản đồ."),
            ["comic.8.2"] = ("Something is tunnelling down here, waiting for the sky to fall.", "Có thứ gì đó đang đào hầm dưới này, chờ bầu trời sụp xuống."),
            ["comic.8.3"] = ("Tartarus stopped short of our base. Thorne is running for the sea.", "Tartarus dừng lại ngay trước căn cứ của ta. Thorne đang chạy ra biển."),
            ["comic.9.1"] = ("His buoys are listening. So now am I.", "Phao của hắn đang nghe lén. Giờ tôi cũng vậy."),
            ["comic.9.2"] = ("Don't let me have been right.", "Đừng để tôi đã đúng."),
            ["comic.9.3"] = ("No body in the wreck. Just a message, four minutes later.", "Không có xác người trong xác tàu. Chỉ có một tin nhắn, bốn phút sau."),
            ["comic.done"] = ("Continue", "Tiếp tục"),
