            ["frontmap.betrayed"] = ("Thorne's army", "Quân của Thorne"),
            ["frontmap.caption"] = ("The front · {won} of {total} missions won", "Mặt trận · đã thắng {won}/{total} nhiệm vụ"),
            ["frontmap.enemy"] = ("Hegemon", "Hegemon"),
            ["frontmap.flag"] = ("Base taken", "Căn cứ đã chiếm"),
            ["frontmap.front"] = ("Front line", "Chiến tuyến"),
            ["frontmap.ours"] = ("Liberated", "Đã giải phóng"),
            ["intel.c1.inspection.from"] = ("Major Brandt, Ashfield", "Thiếu tá Brandt, Ashfield"),
            ["intel.c1.inspection.text"] = ("Bastion Mk.0: plates thinner than drawn, the second gun never fitted. Crew morale good. Request for the missing parts sent to General Varga for the fourth time. I expect no answer.", "Bastion Mk.0: giáp mỏng hơn bản vẽ, khẩu pháo thứ hai chưa bao giờ được lắp. Tinh thần kíp lái tốt. Đã gửi tướng Varga xin phụ tùng còn thiếu lần thứ tư. Tôi không mong có hồi âm."),
            ["intel.c1.inspection.title"] = ("Inspection report", "Biên bản kiểm tra"),
            ["intel.c1.letter.from"] = ("A Hegemon private, Stormbeach", "Một binh nhì Hegemon, Stormbeach"),
            ["intel.c1.letter.text"] = ("Mum, they told us the coast would be quiet work: guard a port, count the ships. Now there are tanks coming out of the sea and nobody tells us anything. Keep my room as it is.", "Mẹ ơi, người ta bảo bờ biển này là việc nhàn: gác cảng, đếm tàu. Giờ thì xe tăng từ dưới biển bò lên mà chẳng ai nói gì với tụi con cả. Mẹ cứ để phòng con như cũ nhé."),
            ["intel.c1.letter.title"] = ("A letter home", "Thư gửi về nhà"),
            ["intel.c10.home.from"] = ("Kasimir Wolff", "Kasimir Wolff"),
            ["intel.c10.home.text"] = ("The Accord boy is good. Better than his friend was. I will enjoy this one. Tell Father the new fighter turns like a thought.", "Thằng nhóc của Accord khá lắm. Giỏi hơn bạn nó ngày trước. Lần này ta sẽ vui đây. Nói với cha là chiếc tiêm kích mới quay nhanh như ý nghĩ."),
            ["intel.c10.home.title"] = ("Raven's letter home", "Thư Raven gửi về nhà"),
            ["intel.c10.test.from"] = ("Director Lucien Aurel", "Giám đốc Lucien Aurel"),
            ["intel.c10.test.text"] = ("Mk.0 flight test complete. Losses to ground fire acceptable. Icarus 01 is ready; 02 and 03 follow on the next launch windows. The brigade need not know there is more than one.", "Hoàn tất bay thử Mk.0. Tổn thất do hỏa lực mặt đất chấp nhận được. Icarus 01 đã sẵn sàng; 02 và 03 sẽ theo ở các khung phóng kế tiếp. Lữ đoàn không cần biết có nhiều hơn một chiếc."),
            ["intel.c10.test.title"] = ("Report: Icarus Mk.0", "Báo cáo: Icarus Mk.0"),
            ["intel.c11.memo.from"] = ("Director Lucien Aurel", "Giám đốc Lucien Aurel"),
            ["intel.c11.memo.text"] = ("The Skygate Array will be defended to the last contract. After Helion there will be no more contracts, only customers.", "Skygate Array sẽ được bảo vệ tới bản hợp đồng cuối cùng. Sau Helion sẽ không còn hợp đồng nào nữa, chỉ còn khách hàng."),
            ["intel.c11.memo.title"] = ("Memo to the board", "Bản ghi nhớ gửi hội đồng"),
            ["intel.c11.orlov.from"] = ("Colonel Ilya Orlov", "Đại tá Ilya Orlov"),
            ["intel.c11.orlov.text"] = ("I have lost the war and my gun on the same day. I find I mind the gun more. Winter always comes back, but not for me.", "Ta mất cả cuộc chiến lẫn khẩu pháo trong cùng một ngày. Hóa ra ta tiếc khẩu pháo hơn. Mùa đông luôn quay lại, nhưng không phải cho ta."),
            ["intel.c11.orlov.title"] = ("Orlov's last letter", "Lá thư cuối của Orlov"),
            ["intel.c12.bargain.from"] = ("Admiral Magnus Kessler", "Đô đốc Magnus Kessler"),
            ["intel.c12.bargain.text"] = ("Terms: every ship and missile I have left, for my sailors' lives. Mine you may keep. I have always known what I am worth.", "Điều kiện: mọi con tàu và tên lửa ta còn lại, đổi lấy mạng sống của thủy thủ. Mạng ta thì cứ giữ lấy. Ta luôn biết mình đáng giá bao nhiêu."),
            ["intel.c12.bargain.title"] = ("Kessler's bargain", "Cuộc mặc cả của Kessler"),
            ["intel.c12.last.from"] = ("A Hegemon private, Dunebreak", "Một binh nhì Hegemon, Dunebreak"),
            ["intel.c12.last.text"] = ("They say it ends at Helion, one way or the other. If the sky lights up, don't look at it. Put the kettle on. I'm coming home.", "Người ta bảo mọi chuyện sẽ kết thúc ở Helion, bằng cách này hay cách khác. Nếu bầu trời sáng rực, mẹ đừng nhìn. Mẹ cứ đun nước đi. Con sắp về rồi."),
            ["intel.c12.last.title"] = ("The last letter", "Lá thư cuối"),
            ["intel.c2.drawings.from"] = ("Engineer Mara Lind", "Kỹ sư Mara Lind"),
            ["intel.c2.drawings.text"] = ("I drew the Behemoth to end a war quickly. That was the pitch, and I believed it. Seven years later it ends nothing, and I am the one who knows where its rear plates are thin.", "Tôi vẽ Behemoth để kết thúc chiến tranh cho nhanh. Người ta chào hàng như thế, và tôi đã tin. Bảy năm sau nó chẳng kết thúc được gì, còn tôi là người biết giáp sau của nó mỏng ở đâu."),
            ["intel.c2.drawings.title"] = ("Mara's diary: the first drawings", "Nhật ký của Mara: những bản vẽ đầu tiên"),
            ["intel.c2.order.from"] = ("General Viktor Varga, Dunebreak", "Tướng Viktor Varga, Dunebreak"),
            ["intel.c2.order.text"] = ("To the Desert Group: the enemy fights for his home. Respect that, and beat him anyway. No well is to be poisoned. Any man who does will answer to me, not to the Director.", "Gửi Cụm Sa mạc: kẻ địch chiến đấu vì nhà cửa của họ. Hãy tôn trọng điều đó, và vẫn phải đánh bại họ. Cấm đầu độc giếng nước. Kẻ nào làm vậy sẽ phải trả lời trước ta, không phải trước Giám đốc."),
            ["intel.c2.order.title"] = ("Order of the day", "Nhật lệnh"),
            ["intel.c3.snow.from"] = ("A Hegemon gunner, Whiteout Pass", "Một pháo thủ Hegemon, Whiteout Pass"),
            ["intel.c3.snow.text"] = ("The Colonel says the cold is on our side. The cold is on nobody's side. Fenrir went out into the storm this morning and the snow closed behind it like a door.", "Đại tá bảo cái lạnh đứng về phía ta. Cái lạnh chẳng đứng về phía ai cả. Sáng nay Fenrir lao vào bão tuyết và tuyết khép lại sau nó như một cánh cửa."),
            ["intel.c3.snow.title"] = ("A letter from the pass", "Thư từ con đèo"),
            ["intel.c3.tables.from"] = ("Colonel Ilya Orlov, Frostpeak", "Đại tá Ilya Orlov, Frostpeak"),
            ["intel.c3.tables.text"] = ("Guns 1 to 9 registered on every road out of the pass. Fire only on the radar's word. Never twice from the same pit. Patience is cheaper than shells.", "Pháo 1 đến 9 đã ngắm sẵn mọi con đường ra khỏi đèo. Chỉ bắn theo lệnh của radar. Không bao giờ bắn hai lần từ cùng một hố. Kiên nhẫn rẻ hơn đạn pháo."),
            ["intel.c3.tables.title"] = ("Firing tables", "Bảng bắn"),
            ["intel.c4.balance.from"] = ("Admiral Magnus Kessler, Iron Harbor", "Đô đốc Magnus Kessler, Iron Harbor"),
            ["intel.c4.balance.text"] = ("Harbour losses this quarter within tolerance. Recommend we stop repairing the docks and let the Accord inherit the cost. A port is an asset until it is a liability.", "Tổn thất cảng quý này trong mức cho phép. Đề nghị ngừng sửa bến và để Accord gánh chi phí. Một hải cảng là tài sản cho tới khi nó thành gánh nặng."),
            ["intel.c4.balance.title"] = ("The balance sheet", "Bảng cân đối"),
            ["intel.c4.flank.from"] = ("Intercepted by Captain Nadia Kerr", "Đại úy Nadia Kerr chặn được"),
            ["intel.c4.flank.text"] = ("Column to move at 06:00 and cover the brigade's left. Overwritten at 05:40 by Thorne's own HQ: hold in place, fuel shortage. The fuel depot's log shows full tanks.", "Đoàn xe xuất phát lúc 06:00 để che sườn trái của lữ đoàn. Lúc 05:40 bị chính sở chỉ huy của Thorne ghi đè: giữ nguyên vị trí, thiếu nhiên liệu. Sổ kho xăng ghi các bồn vẫn đầy."),
            ["intel.c4.flank.title"] = ("Movement order, Thorne's column", "Lệnh hành quân, đoàn xe của Thorne"),
            ["intel.c4.prisoner.from"] = ("A prisoner, Rust Yard", "Một tù nhân, Rust Yard"),
            ["intel.c4.prisoner.text"] = ("If you find this, we are in the third wagon. They feed us once a day and count us twice. Tell my sister I did not sign anything.", "Nếu ai thấy mẩu giấy này, chúng tôi ở toa thứ ba. Chúng cho ăn một lần một ngày và điểm danh hai lần. Nhắn em gái tôi là tôi không ký gì cả."),
            ["intel.c4.prisoner.title"] = ("A note from the train", "Mẩu giấy trên tàu"),
            ["intel.c5.notebook.from"] = ("Dr Elara Venn", "Tiến sĩ Elara Venn"),
            ["intel.c5.notebook.text"] = ("A swarm can search a collapsed building in four minutes. I built it for earthquakes. The board asked how many warheads it could carry. I should have left then.", "Một bầy drone có thể lục soát một tòa nhà sập trong bốn phút. Tôi làm ra nó cho những trận động đất. Hội đồng hỏi nó mang được bao nhiêu đầu đạn. Lẽ ra tôi phải đi ngay lúc đó."),
            ["intel.c5.notebook.title"] = ("Venn's notes: the swarm", "Ghi chép của Venn: bầy drone"),
            ["intel.c5.titan.from"] = ("Captain Nadia Kerr", "Đại úy Nadia Kerr"),
            ["intel.c5.titan.text"] = ("Venn's hangars logged six calls from a station signing as Titan, the Accord's call sign for General Thorne. The calls came on our frequencies, at hours our own logs show as silent.", "Nhà chứa của Venn ghi lại sáu cuộc gọi từ một trạm ký tên Titan, mật danh của Accord dành cho tướng Thorne. Các cuộc gọi đến trên tần số của ta, vào những giờ sổ trực của ta ghi là im lặng."),
            ["intel.c5.titan.title"] = ("Signal log: Titan", "Nhật ký tín hiệu: Titan"),
            ["intel.c5.village.from"] = ("The charcoal burners, Jungle Pass", "Những người đốt than, Jungle Pass"),
            ["intel.c5.village.text"] = ("The drones fly over us every night and never fire. We think they are counting us. The children have started waving at them.", "Đêm nào drone cũng bay qua đầu mà không bắn. Chúng tôi nghĩ chúng đang đếm người. Bọn trẻ bắt đầu vẫy tay chào chúng."),
            ["intel.c5.village.title"] = ("A letter from the canopy", "Thư từ rừng sâu"),
            ["intel.c6.band.from"] = ("Captain Nadia Kerr", "Đại úy Nadia Kerr"),
            ["intel.c6.band.text"] = ("For one hour on the night before the dam, Thorne's HQ transmitter worked on a Hegemon band. In the same hour Varga's guns fell silent. I have told no one yet. I want to be wrong.", "Trong một tiếng đêm trước trận đập, máy phát của sở chỉ huy Thorne chạy trên băng tần của Hegemon. Đúng tiếng ấy pháo của Varga im bặt. Tôi chưa nói với ai. Tôi muốn mình sai."),
            ["intel.c6.band.title"] = ("Signal log: Hollow Dam", "Nhật ký tín hiệu: Hollow Dam"),
            ["intel.c6.board.from"] = ("Director Lucien Aurel", "Giám đốc Lucien Aurel"),
            ["intel.c6.board.text"] = ("The Varga counterstrike buys Project Icarus four months. The general believes he is winning a war. He is buying time for the only weapon that matters.", "Cuộc phản công của Varga mua cho Dự án Icarus bốn tháng. Vị tướng tin rằng ông ta đang thắng một cuộc chiến. Thực ra ông ta chỉ đang câu giờ cho thứ vũ khí duy nhất đáng kể."),
            ["intel.c6.board.title"] = ("Report to the board", "Báo cáo gửi hội đồng"),
            ["intel.c6.raiders.from"] = ("A Hegemon driver, Hollow Dam", "Một lính lái xe Hegemon, Hollow Dam"),
            ["intel.c6.raiders.text"] = ("General Varga came down to the vehicle park himself and asked our names. Twenty years in, and nobody from the top ever did that. We will hold this dam for him.", "Tướng Varga đích thân xuống bãi xe và hỏi tên từng người. Hai mươi năm quân ngũ, chưa ai ở trên làm vậy. Tụi tôi sẽ giữ con đập này vì ông ấy."),
            ["intel.c6.raiders.title"] = ("A letter from the dam", "Thư từ con đập"),
            ["intel.c7.letters.from"] = ("The post office, Veyra", "Bưu điện Veyra"),
            ["intel.c7.letters.text"] = ("Two years of letters that were never delivered, sorted by street. The brigade's drivers took them round in the evenings. Some doors had no one left to open them.", "Thư từ suốt hai năm chưa từng được phát, xếp theo từng con phố. Lính lái xe của lữ đoàn đi phát vào mỗi buổi tối. Có những cánh cửa không còn ai để mở."),
            ["intel.c7.letters.title"] = ("Letters from Veyra", "Những lá thư từ Veyra"),
            ["intel.c7.turn.from"] = ("Captain Nadia Kerr", "Đại úy Nadia Kerr"),
            ["intel.c7.turn.text"] = ("At 14:02 Thorne's base turned its guns inward. I had the file for six weeks: the column, Titan, the dam. I should have sent it after the second clue. I will not wait again.", "Lúc 14:02 căn cứ của Thorne quay nòng pháo vào trong. Tôi đã giữ hồ sơ suốt sáu tuần: đoàn xe, Titan, con đập. Lẽ ra tôi phải gửi nó sau manh mối thứ hai. Tôi sẽ không chờ nữa."),
            ["intel.c7.turn.title"] = ("Nadia's report: the turn", "Báo cáo của Nadia: cú phản bội"),
            ["intel.c8.fortress.from"] = ("Engineer Mara Lind", "Kỹ sư Mara Lind"),
            ["intel.c8.fortress.text"] = ("The survey maps show tunnels cut for something wide and heavy, and bunkers facing up, not out. This is not a mine. It is a shelter, for when the sky starts falling.", "Bản đồ khảo sát cho thấy đường hầm được đào cho một thứ vừa rộng vừa nặng, và những hầm ngầm hướng lên trời chứ không hướng ra ngoài. Đây không phải mỏ. Đây là chỗ trú ẩn, cho lúc bầu trời bắt đầu sụp xuống."),
            ["intel.c8.fortress.title"] = ("Mara's diary: the fortress below", "Nhật ký của Mara: pháo đài dưới lòng đất"),
            ["intel.c8.letter.from"] = ("General Roland Thorne, to Director Aurel", "Tướng Roland Thorne, gửi Giám đốc Aurel"),
            ["intel.c8.letter.text"] = ("You promised me the coast when Icarus flies. I have kept my part: the Accord's best army is out of your way. Keep yours, or I will find out what your satellites cost to shoot down.", "Ông đã hứa trao dải bờ biển cho tôi khi Icarus cất cánh. Tôi đã làm xong phần mình: đạo quân giỏi nhất của Accord đã tránh khỏi đường ông. Hãy giữ lời, không thì tôi sẽ tìm hiểu bắn hạ vệ tinh của ông tốn bao nhiêu."),
            ["intel.c8.letter.title"] = ("Thorne's letter", "Thư của Thorne"),
            ["intel.c9.buoy.from"] = ("Captain Nadia Kerr", "Đại úy Nadia Kerr"),
            ["intel.c9.buoy.text"] = ("I ran the buoy's message through Thorne's old codebooks. Under the coordinates there is a second line, addressed to nobody: \"Still here.\" The buoy has not answered since.", "Tôi giải tin nhắn từ cái phao bằng sổ mật mã cũ của Thorne. Dưới dòng tọa độ còn một dòng thứ hai, không gửi cho ai: \"Vẫn ở đây.\" Từ đó cái phao không trả lời nữa."),
            ["intel.c9.buoy.title"] = ("The second line", "Dòng thứ hai"),
            ["intel.c9.timetable.from"] = ("Admiral Magnus Kessler", "Đô đốc Magnus Kessler"),
            ["intel.c9.timetable.text"] = ("Minelayers to sail at 02:00, 02:20 and 02:40. Crews to be paid on return. Note: there may be no return. Pay them anyway; it is good for the others to see.", "Tàu rải mìn xuất phát lúc 02:00, 02:20 và 02:40. Trả lương thủy thủ khi quay về. Ghi chú: có thể sẽ không ai quay về. Cứ trả lương, để những người khác thấy."),
            ["intel.c9.timetable.title"] = ("The last timetable", "Thời gian biểu cuối cùng"),
            ["intel.i1.initials.from"] = ("Engineer Mara Lind", "Kỹ sư Mara Lind"),
            ["intel.i1.initials.text"] = ("They left my initials on the hull. Maybe it was spite, maybe pride. I scratched them off with a screwdriver while Kade pretended not to watch.", "Họ để nguyên chữ ký tắt của tôi trên thân xe. Có thể vì hằn học, có thể vì tự hào. Tôi cạo nó đi bằng tua vít trong lúc Kade giả vờ không nhìn."),
            ["intel.i1.initials.title"] = ("Mara's diary: initials", "Nhật ký của Mara: chữ ký tắt"),
            ["intel.i1.ledger.from"] = ("Major Otto Brenn", "Thiếu tá Otto Brenn"),
            ["intel.i1.ledger.text"] = ("Page 212: one Behemoth, prototype, its cost carried over from a cancelled contract, signed M. L. The quartermaster underlined the initials twice and closed the book.", "Trang 212: một Behemoth nguyên mẫu, chi phí chuyển từ một hợp đồng đã hủy, ký tên M. L. Người quản lý hậu cần gạch dưới chữ ký tắt hai lần rồi gấp sổ lại."),
            ["intel.i1.ledger.title"] = ("Brenn's ledger", "Sổ cái của Brenn"),
            ["intel.i2.escort.from"] = ("Captain Kaia Mendez", "Đại úy Kaia Mendez"),
            ["intel.i2.escort.text"] = ("Package asleep in the third truck, arms round a hard drive. Asked twice whether we would hand her to the Accord's courts. I said I drive, I do not judge.", "Người cần hộ tống ngủ ở thùng xe thứ ba, ôm khư khư một ổ cứng. Hỏi hai lần liệu chúng tôi có giao cô ấy cho tòa án của Accord không. Tôi bảo tôi chỉ lái xe, không phán xử."),
            ["intel.i2.escort.title"] = ("Escort log", "Nhật ký hộ tống"),
            ["intel.i2.stay.from"] = ("Dr Elara Venn", "Tiến sĩ Elara Venn"),
            ["intel.i2.stay.text"] = ("They could have left me at the border with a car and papers. Instead the brigade's engineer asked me to help her take my machines apart. Nobody had ever asked me to take anything apart.", "Họ có thể để tôi lại ở biên giới với một chiếc xe và giấy tờ. Thay vào đó, kỹ sư của lữ đoàn nhờ tôi giúp tháo dỡ những cỗ máy của chính tôi. Chưa ai từng nhờ tôi tháo dỡ thứ gì."),
            ["intel.i2.stay.title"] = ("Venn's notes: why I stayed", "Ghi chép của Venn: vì sao tôi ở lại"),
            ["intel.i3.crown.from"] = ("Colonel August Reyn", "Đại tá August Reyn"),
            ["intel.i3.crown.text"] = ("Crown to all: we bring the pilot home. Nothing else on this road is worth a vehicle. If the ring does not break, we make it break.", "Crown gửi toàn đoàn: ta đưa phi công về nhà. Trên con đường này không có gì khác đáng một chiếc xe. Nếu vòng vây không vỡ, ta làm cho nó vỡ."),
            ["intel.i3.crown.title"] = ("Column orders", "Lệnh hành quân của đoàn"),
            ["intel.i3.log.from"] = ("Lieutenant Jonah Reyes", "Trung úy Jonah Reyes"),
            ["intel.i3.log.text"] = ("Hit at nine thousand feet, left engine gone. Saw the black fighter turn for a second pass and not come. He wanted me alive, to hunt. His mistake.", "Trúng đạn ở độ cao chín nghìn bộ, động cơ trái hỏng. Thấy chiếc tiêm kích đen quay lại lượt thứ hai rồi không tới. Hắn muốn tôi sống, để săn. Sai lầm của hắn."),
            ["intel.i3.log.title"] = ("Hawk's flight log", "Nhật ký bay của Hawk"),
            ["loot.cruise_missile"] = ("Kessler's last bargain: his cruise missiles, for his sailors' lives.", "Cuộc mặc cả cuối cùng của Kessler: tên lửa hành trình của hắn, đổi lấy mạng sống thủy thủ."),
            ["loot.railgun_truck"] = ("Tempest's rail gun came out of the wreck whole; Mara built a truck round it.", "Pháo điện từ của Tempest được vớt lên nguyên vẹn; Mara dựng cả một chiếc xe quanh nó."),
            ["loot.swarm_carrier"] = ("Venn came over with the plans for her drone mothership, and the Accord built it.", "Venn mang theo bản vẽ máy bay mẹ thả drone của bà khi đào ngũ, và Accord đã chế tạo nó."),
            ["radio.aurel.react.air.1"] = ("You reach for the sky. It is already taken.", "Ông với tay lên trời. Nhưng nó đã có chủ."),
            ["radio.aurel.react.air.2"] = ("Aircraft. How quaint, beneath a satellite.", "Máy bay. Thật cổ kính, dưới một vệ tinh."),
            ["radio.aurel.react.artillery.1"] = ("Guns. You fight with the last century's tools.", "Pháo. Ông chiến đấu bằng công cụ của thế kỷ trước."),
            ["radio.aurel.react.artillery.2"] = ("Your shells fall. Mine will fall from much higher.", "Đạn của ông rơi xuống. Đạn của tôi sẽ rơi từ cao hơn nhiều."),
            ["radio.aurel.react.drones.1"] = ("Venn's work, turned against me. She will regret it.", "Công trình của Venn, quay lại chống tôi. Cô ta sẽ hối hận."),
            ["radio.aurel.react.drones.2"] = ("Drones. Small ideas. I prefer large ones.", "Drone. Những ý tưởng nhỏ. Tôi thích ý tưởng lớn hơn."),
            ["radio.aurel.react.fast.1"] = ("Efficient, Colonel. The sky rewards efficiency.", "Hiệu quả đấy, đại tá. Bầu trời thưởng cho sự hiệu quả."),
            ["radio.aurel.react.fast.2"] = ("You win quickly. You will lose quickly too.", "Ông thắng nhanh. Ông cũng sẽ thua nhanh thôi."),
            ["radio.aurel.react.interrupt.1"] = ("A delay. Only a delay.", "Một sự trì hoãn. Chỉ là trì hoãn thôi."),
            ["radio.aurel.react.interrupt.2"] = ("You interrupted the strike. The next will not ask.", "Ông ngắt được đòn đánh. Đòn tiếp theo sẽ không hỏi ý ông đâu."),
            ["radio.aurel.react.losses.1"] = ("Your losses are the ground's losses. The sky loses nothing.", "Tổn thất của ông là tổn thất của mặt đất. Bầu trời chẳng mất gì."),
            ["radio.aurel.react.losses.2"] = ("Count them, Colonel. From orbit they are very small.", "Đếm đi, đại tá. Nhìn từ quỹ đạo, chúng nhỏ xíu."),
            ["radio.brandt.react.air.1"] = ("Aircraft over my walls. Gunners, look up.", "Máy bay trên đầu tường thành. Pháo thủ, nhìn lên."),
            ["radio.brandt.react.air.2"] = ("You fly over walls you cannot break. Clever.", "Ông bay qua những bức tường ông không phá nổi. Khôn đấy."),
            ["radio.brandt.react.artillery.1"] = ("Shells on my walls all day. At least you respect them.", "Đạn pháo dội vào tường tôi suốt ngày. Ít ra ông cũng nể chúng."),
            ["radio.brandt.react.artillery.2"] = ("Your guns are good. My concrete is better.", "Pháo của ông tốt. Bê tông của tôi tốt hơn."),
            ["radio.brandt.react.drones.1"] = ("Drones in the trenches. Nets up, all of you.", "Drone trong chiến hào. Tất cả giăng lưới lên."),
            ["radio.brandt.react.drones.2"] = ("Little machines, big noise. My men have seen worse.", "Máy nhỏ, tiếng to. Người của tôi từng gặp chuyện tệ hơn."),
            ["radio.brandt.react.fast.1"] = ("Faster than my drills allowed for. Noted, Colonel.", "Nhanh hơn mọi bài tập của tôi tính tới. Ghi nhận, đại tá."),
            ["radio.brandt.react.fast.2"] = ("My walls were built for a siege, not a sprint.", "Tường của tôi xây để chống vây hãm, không phải để chạy nước rút."),
            ["radio.brandt.react.interrupt.1"] = ("You broke the shot before it fired. I trained that crew myself.", "Ông phá phát bắn trước khi nó kịp nổ. Kíp đó do chính tôi huấn luyện."),
            ["radio.brandt.react.interrupt.2"] = ("Stopped cold. Reload and try again.", "Bị chặn đứng. Nạp đạn lại và thử lần nữa."),
            ["radio.brandt.react.losses.1"] = ("Your wrecks are piling up at my wall. Walls are patient.", "Xác xe của ông chất đống dưới chân tường tôi. Tường thì kiên nhẫn lắm."),
            ["radio.brandt.react.losses.2"] = ("Count your losses, Colonel. I count mine every night.", "Đếm tổn thất đi, đại tá. Tôi thì đêm nào cũng đếm của mình."),
            ["radio.hung.react.air.1"] = ("Planes. Icarus will own that sky soon. Enjoy it.", "Máy bay. Chẳng bao lâu nữa Icarus sẽ làm chủ bầu trời đó. Tận hưởng đi."),
            ["radio.hung.react.air.2"] = ("Air cover. I taught you that, Kade.", "Yểm trợ trên không. Tôi dạy anh chiêu đó đấy, Kade."),
            ["radio.hung.react.artillery.1"] = ("Artillery. Still the careful one, Kade.", "Pháo binh. Vẫn cẩn thận như xưa, Kade."),
            ["radio.hung.react.artillery.2"] = ("Dahl's guns. I signed his promotion, you know.", "Pháo của Dahl. Anh biết không, chính tôi ký lệnh thăng chức cho cậu ta."),
            ["radio.hung.react.drones.1"] = ("Venn's drones on my lines. So she chose you.", "Drone của Venn trên phòng tuyến của tôi. Vậy là cô ấy chọn anh."),
            ["radio.hung.react.drones.2"] = ("Drones everywhere. You fight like Hegemon now.", "Drone khắp nơi. Giờ anh đánh như Hegemon rồi đấy."),
            ["radio.hung.react.fast.1"] = ("Fast, Kade. You always were, when it mattered.", "Nhanh đấy, Kade. Anh luôn nhanh, khi cần."),
            ["radio.hung.react.fast.2"] = ("Quick work. You would have made a fine general of mine.", "Gọn gàng. Anh mà theo tôi thì sẽ là một vị tướng giỏi."),
            ["radio.hung.react.interrupt.1"] = ("You broke it in time. Of course you did.", "Anh phá được nó kịp lúc. Tất nhiên rồi."),
            ["radio.hung.react.interrupt.2"] = ("Stopped. You always find the weak point, Kade.", "Bị chặn rồi. Anh luôn tìm ra điểm yếu, Kade."),
            ["radio.hung.react.losses.1"] = ("You're bleeding, Kade. Is the Accord worth it?", "Anh đang mất máu đấy, Kade. Accord có đáng không?"),
            ["radio.hung.react.losses.2"] = ("Your losses, not mine. For once.", "Tổn thất của anh, không phải của tôi. Lần này thôi."),
            ["radio.kessler.react.air.1"] = ("Aircraft cost more than ships. I checked.", "Máy bay đắt hơn tàu. Ta đã kiểm tra rồi."),
            ["radio.kessler.react.air.2"] = ("Planes over my harbour. Anti-air, earn your pay.", "Máy bay trên cảng của ta. Phòng không, làm cho xứng đồng lương."),
            ["radio.kessler.react.artillery.1"] = ("Shelling my docks. Who pays to rebuild them, Colonel?", "Pháo kích bến cảng của ta. Ai trả tiền xây lại, đại tá?"),
            ["radio.kessler.react.artillery.2"] = ("Guns from far off. Safe, and slow. Like a bank.", "Pháo từ xa. An toàn, và chậm. Như ngân hàng."),
            ["radio.kessler.react.drones.1"] = ("Drones: cheap, and plenty of them. I approve.", "Drone: rẻ, và nhiều. Ta tán thành."),
            ["radio.kessler.react.drones.2"] = ("A swarm. Venn would send you an invoice for that.", "Một bầy drone. Venn sẽ gửi hóa đơn cho ngươi đấy."),
            ["radio.kessler.react.fast.1"] = ("Quick. Expensive for me. Noted in the ledger.", "Nhanh. Tốn kém cho ta. Đã ghi vào sổ."),
            ["radio.kessler.react.fast.2"] = ("You finish early. Time is money, and you are taking mine.", "Ngươi xong sớm. Thời gian là tiền bạc, và ngươi đang lấy của ta."),
            ["radio.kessler.react.interrupt.1"] = ("The salvo is lost. Write it off.", "Mất loạt đạn rồi. Xóa sổ đi."),
            ["radio.kessler.react.interrupt.2"] = ("You broke my broadside. That will cost you.", "Ngươi phá loạt pháo mạn của ta. Chuyện đó sẽ đắt cho ngươi."),
            ["radio.kessler.react.losses.1"] = ("Your losses are mounting. Can you afford this war?", "Tổn thất của ngươi đang tăng. Ngươi có kham nổi cuộc chiến này không?"),
            ["radio.kessler.react.losses.2"] = ("A poor exchange rate, Colonel. Poor indeed.", "Tỷ giá tệ đấy, đại tá. Tệ thật."),
            ["radio.orlov.react.air.1"] = ("Aircraft in my sky. The radar sees them all.", "Máy bay trên trời của ta. Radar thấy hết."),
            ["radio.orlov.react.air.2"] = ("Fly, then. The cold brings down more than guns do.", "Cứ bay đi. Cái lạnh hạ được nhiều hơn pháo."),
            ["radio.orlov.react.artillery.1"] = ("A gunner's war. At last, someone who understands.", "Một cuộc chiến của pháo thủ. Cuối cùng cũng có người hiểu."),
            ["radio.orlov.react.artillery.2"] = ("Counter-battery, all guns. Find his pits.", "Phản pháo, tất cả các khẩu. Tìm hố pháo của hắn."),
            ["radio.orlov.react.drones.1"] = ("Small drones freeze, Colonel. Wait for it.", "Drone nhỏ sẽ đóng băng, đại tá. Cứ chờ xem."),
            ["radio.orlov.react.drones.2"] = ("Drones in a blizzard. Brave, or foolish.", "Drone giữa bão tuyết. Dũng cảm, hoặc ngu ngốc."),
            ["radio.orlov.react.fast.1"] = ("Too fast. My guns never finished ranging.", "Quá nhanh. Pháo của ta chưa kịp chỉnh tầm."),
            ["radio.orlov.react.fast.2"] = ("You ran through my winter. It will remember.", "Ngươi chạy xuyên qua mùa đông của ta. Nó sẽ nhớ."),
            ["radio.orlov.react.interrupt.1"] = ("Fire mission cancelled. Recalculate.", "Hủy nhiệm vụ bắn. Tính lại."),
            ["radio.orlov.react.interrupt.2"] = ("You broke my shot. Nobody breaks my shot.", "Ngươi phá phát bắn của ta. Chưa ai làm được thế."),
            ["radio.orlov.react.losses.1"] = ("The snow is full of your wrecks. Patience wins.", "Tuyết đầy xác xe của ngươi. Kiên nhẫn sẽ thắng."),
            ["radio.orlov.react.losses.2"] = ("Every loss is a lesson. You learn slowly.", "Mỗi tổn thất là một bài học. Ngươi học chậm quá."),
            ["radio.quaden.react.air.1"] = ("More planes for me to shoot. Thank you, Colonel.", "Thêm máy bay cho ta bắn. Cảm ơn, đại tá."),
            ["radio.quaden.react.air.2"] = ("Your pilots are brave. Bravery burns nicely.", "Phi công của ông dũng cảm. Lòng dũng cảm cháy đẹp lắm."),
            ["radio.quaden.react.artillery.1"] = ("Guns on the ground. How very old-fashioned.", "Pháo dưới đất. Thật là cổ lỗ."),
            ["radio.quaden.react.artillery.2"] = ("Shells can't climb, Colonel. I can.", "Đạn pháo không leo lên được, đại tá. Ta thì được."),
            ["radio.quaden.react.drones.1"] = ("Drones? I do not dogfight toasters.", "Drone à? Ta không không chiến với lò nướng bánh."),
            ["radio.quaden.react.drones.2"] = ("A sky full of drones. Clutter.", "Bầu trời đầy drone. Toàn rác."),
            ["radio.quaden.react.fast.1"] = ("Quick, Colonel. Too quick to be fun.", "Nhanh đấy, đại tá. Nhanh quá thì mất vui."),
            ["radio.quaden.react.fast.2"] = ("Over already? I barely warmed up the engines.", "Xong rồi à? Ta còn chưa kịp làm nóng động cơ."),
            ["radio.quaden.react.interrupt.1"] = ("You broke my attack run? Lucky.", "Ông phá được đợt tấn công của ta ư? May mắn thôi."),
            ["radio.quaden.react.interrupt.2"] = ("Missed my window. It will not happen twice.", "Lỡ thời cơ rồi. Chuyện đó không lặp lại lần hai đâu."),
            ["radio.quaden.react.losses.1"] = ("Burning wrecks everywhere. Beautiful from up here.", "Xác xe cháy khắp nơi. Nhìn từ trên này đẹp lắm."),
            ["radio.quaden.react.losses.2"] = ("Your losses make good target practice.", "Tổn thất của ông là bài tập bắn tốt đấy."),
            ["radio.sen.react.air.1"] = ("Aircraft. The swarm routes around them.", "Máy bay. Bầy drone đổi hướng tránh chúng."),
            ["radio.sen.react.air.2"] = ("You bring planes to a drone fight. Bold.", "Ông mang máy bay tới trận đánh drone. Táo bạo đấy."),
            ["radio.sen.react.artillery.1"] = ("Artillery. Blunt, but the swarm cannot dodge it.", "Pháo binh. Thô, nhưng bầy drone không né được."),
            ["radio.sen.react.artillery.2"] = ("Shells through the canopy. The forest is burning, Colonel.", "Đạn pháo xuyên tán rừng. Khu rừng đang cháy, đại tá."),
            ["radio.sen.react.drones.1"] = ("You use drones too. Now we are having a conversation.", "Ông cũng dùng drone. Giờ ta mới thực sự nói chuyện."),
            ["radio.sen.react.drones.2"] = ("Your drones are clumsy. Mine were built to be gentle.", "Drone của ông vụng về quá. Drone của tôi được tạo ra để nhẹ nhàng."),
            ["radio.sen.react.fast.1"] = ("Faster than my models predicted. Interesting.", "Nhanh hơn mô hình của tôi dự đoán. Thú vị."),
            ["radio.sen.react.fast.2"] = ("You adapt faster than the swarm does. That worries me.", "Ông thích nghi nhanh hơn bầy drone. Điều đó làm tôi lo."),
            ["radio.sen.react.interrupt.1"] = ("You stopped the launch. Good. I mean... noted.", "Ông chặn được đợt phóng. Tốt. Ý tôi là... ghi nhận."),
            ["radio.sen.react.interrupt.2"] = ("The swarm lost its signal. You found the weak link.", "Bầy drone mất tín hiệu. Ông tìm ra mắt xích yếu rồi."),
            ["radio.sen.react.losses.1"] = ("You are losing a lot of machines. Pull back, please.", "Ông đang mất nhiều xe lắm. Rút lui đi, làm ơn."),
            ["radio.sen.react.losses.2"] = ("The swarm counts your losses. I wish it would not.", "Bầy drone đang đếm tổn thất của ông. Tôi mong nó đừng đếm."),
            ["radio.varga.react.air.1"] = ("Planes over the desert. The sand eats engines, Colonel.", "Máy bay trên sa mạc. Cát ăn động cơ đấy, đại tá."),
            ["radio.varga.react.air.2"] = ("You fight from the sky now. My guns look up too.", "Giờ ông đánh từ trên trời. Pháo của ta cũng biết ngẩng lên."),
            ["radio.varga.react.artillery.1"] = ("Your guns are patient. So am I.", "Pháo của ông kiên nhẫn. Ta cũng vậy."),
            ["radio.varga.react.artillery.2"] = ("Shells from far away. Come closer, Colonel.", "Đạn pháo từ xa. Lại gần hơn đi, đại tá."),
            ["radio.varga.react.drones.1"] = ("Drones. Venn's toys. I prefer an honest tank.", "Drone. Đồ chơi của Venn. Ta thích một chiếc xe tăng đàng hoàng hơn."),
            ["radio.varga.react.drones.2"] = ("A swarm of little machines. War is getting smaller.", "Một bầy máy nhỏ. Chiến tranh đang nhỏ lại."),
            ["radio.varga.react.fast.1"] = ("Quick work, Colonel. I would have liked a longer fight.", "Nhanh gọn đấy, đại tá. Ta đã mong một trận dài hơn."),
            ["radio.varga.react.fast.2"] = ("You move like my old regiment did. That is a compliment.", "Ông cơ động như trung đoàn cũ của ta. Đó là lời khen."),
            ["radio.varga.react.interrupt.1"] = ("You broke its stroke. Mara taught you well.", "Ông bẻ gãy đòn của nó. Mara dạy ông giỏi đấy."),
            ["radio.varga.react.interrupt.2"] = ("Stopped before the shot. The old ways still work.", "Chặn được trước phát bắn. Cách cũ vẫn hiệu quả."),
            ["radio.varga.react.losses.1"] = ("You are spending men, Colonel. Steel is cheaper.", "Ông đang tiêu hao người đấy, đại tá. Thép rẻ hơn."),
            ["radio.varga.react.losses.2"] = ("Pull your wounded back. I will not fire on them.", "Rút thương binh của ông về đi. Ta sẽ không bắn vào họ."),
            ["result.intel"] = ("Intel file recovered: {title}", "Thu được tài liệu tình báo: {title}"),
            ["storychoice.c11.radar.body"] = ("The Skygate Array sees everything from here to Helion. Burn its radar first and Hegemon fights the last battle half blind. Or take the service road straight to the pads, fast, and be a day ahead.", "Skygate Array nhìn thấy mọi thứ từ đây tới Helion. Đốt radar của nó trước và Hegemon sẽ đánh trận cuối trong cảnh nửa mù. Hoặc đi đường công vụ thẳng tới các bệ phóng, thật nhanh, và đi trước chúng một ngày."),
            ["storychoice.c11.radar.launch"] = ("Go straight in", "Đi thẳng vào"),
            ["storychoice.c11.radar.launch.info"] = ("The Short Road: a fast look at the pads. Pays more coins and rare blueprints.", "Đường tắt: trinh sát nhanh các bệ phóng. Nhận thêm xu và bản thiết kế hiếm."),
            ["storychoice.c11.radar.radar"] = ("Blind the radar", "Làm mù radar"),
            ["storychoice.c11.radar.radar.info"] = ("Blind the Array: the enemy sees {share}% less in every chapter 12 battle.", "Làm mù Skygate: địch nhìn kém đi {share}% trong mọi trận của chương 12."),
            ["storychoice.c11.radar.title"] = ("The Array", "Skygate Array"),
            ["storychoice.c4.pursuit.body"] = ("Kessler is racing for the sea with his staff and his charts of the coast. Three ferries full of families are still tied up under his rearguard's guns. There is time for one of them, Colonel.", "Kessler đang lao ra biển cùng bộ tham mưu và hải đồ của cả dải bờ biển. Ba chiếc phà đầy các gia đình vẫn còn neo dưới họng pháo của đội đoạn hậu. Chỉ kịp lo một việc thôi, đại tá."),
            ["storychoice.c4.pursuit.harbour"] = ("Save the ferries", "Cứu những chuyến phà"),
            ["storychoice.c4.pursuit.harbour.info"] = ("Harbour Lights: hold the terminal until the ferries are out. Pays rare blueprints.", "Đèn bến cảng: giữ nhà ga cho tới khi phà ra khơi. Nhận bản thiết kế hiếm."),
            ["storychoice.c4.pursuit.sea"] = ("Chase Kessler", "Đuổi theo Kessler"),
            ["storychoice.c4.pursuit.sea.info"] = ("Last Boats: catch his staff cars on the quays. Pays more coins.", "Những chuyến tàu cuối: chặn xe tham mưu trên cầu tàu. Nhận nhiều xu hơn."),
            ["storychoice.c4.pursuit.title"] = ("Kessler Runs", "Kessler bỏ chạy"),
            ["storychoice.c8.miners.body"] = ("Thorne is holding three hundred miners in the pit's camps. Or we go straight for Tartarus's power line while his paymaster sits beside it. We can't do both before Tartarus moves.", "Thorne đang giữ ba trăm thợ mỏ trong các lán trại dưới hố. Hoặc ta đánh thẳng vào đường điện của Tartarus trong lúc viên quản lương của hắn còn ngồi cạnh đó. Không kịp làm cả hai trước khi Tartarus di chuyển."),
            ["storychoice.c8.miners.direct"] = ("Strike Tartarus", "Đánh thẳng Tartarus"),
            ["storychoice.c8.miners.direct.info"] = ("Straight at Tartarus: cut its power and take Thorne's pay chest. Pays twice the coins.", "Đánh thẳng vào Tartarus: cắt điện và lấy hòm lương của Thorne. Nhận gấp đôi xu."),
            ["storychoice.c8.miners.rescue"] = ("Free the miners", "Giải cứu thợ mỏ"),
            ["storychoice.c8.miners.rescue.info"] = ("The Miners of Deepcut: sixty of them join the brigade, +{cp} CP at the start of every chapter 9 battle.", "Thợ mỏ Deepcut: sáu mươi người gia nhập lữ đoàn, +{cp} CP khi bắt đầu mỗi trận của chương 9."),
            ["storychoice.c8.miners.title"] = ("The Miners", "Những người thợ mỏ"),
            ["storyeffect.c11.radar.radar"] = ("The Skygate Array is dark: the enemy sees {share}% less.", "Skygate Array đã tắt: địch nhìn kém đi {share}%."),
            ["storyeffect.c8.miners.rescue"] = ("Deepcut's miners fight with you: +{cp} CP at the start.", "Thợ mỏ Deepcut chiến đấu cùng ta: +{cp} CP khi bắt đầu."),
        };
    }
}
